<?php
session_start(); if(!isset($_SESSION['id'],$_SESSION['role'])||!in_array($_SESSION['role'],['student','faculty','admin'],true)){header('Location:login.php');exit;}include 'db.php';
$q=trim($_GET['q']??''); $uid=(int)$_SESSION['id']; $role=$_SESSION['role'];
if($q!==''){ $stmt=$conn->prepare('SELECT * FROM books WHERE book_name LIKE ? OR author LIKE ? OR category LIKE ? ORDER BY id DESC'); $like="%$q%";$stmt->bind_param('sss',$like,$like,$like);$stmt->execute();$result=$stmt->get_result(); } else {$result=$conn->query('SELECT * FROM books ORDER BY id DESC');}
$admin=$role==='admin';$canBorrow=in_array($role,['student','faculty'],true);
$activeBooks=[];
if($canBorrow){$s=$conn->prepare("SELECT book_id FROM borrowings WHERE member_id=? AND status='issued'");$s->bind_param('i',$uid);$s->execute();$rr=$s->get_result();while($x=$rr->fetch_assoc())$activeBooks[(int)$x['book_id']]=true;$s->close();}
$error=$_GET['error']??'';
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Books | BookNest</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><header class="topbar"><a class="top-brand" href="dashboard.php">📚 BookNest <small>Library</small></a><div class="user-chip"><?= $role==='student'?'🎓':($role==='faculty'?'👨‍🏫':'🛡️') ?> <?=htmlspecialchars($_SESSION['name'])?><span class="role-pill"><?=ucfirst($role)?></span></div></header><main class="page-content"><div class="page-head"><div><div class="eyebrow">LIBRARY COLLECTION</div><h1>📖 Books</h1><p><?= $admin?'Manage the library collection.':'Search the collection and borrow available books.' ?></p></div><div class="head-actions"><a class="secondary-btn" href="dashboard.php">🏠 Dashboard</a><?php if($admin): ?><a class="primary-small" href="add_book.php">➕ Add Book</a><?php endif; ?></div></div><?php if($error): ?><div class="alert error"><?php $msgs=['unavailable'=>'This book is currently unavailable.','already'=>'You already have this book issued.','limit'=>'You reached your active-book limit.','failed'=>'The borrowing request could not be completed.','notfound'=>'Book not found.','has_history'=>'This book has borrowing history and cannot be deleted.']; echo htmlspecialchars($msgs[$error]??'Something went wrong.'); ?></div><?php endif; ?><div class="search-box"><form method="GET"><input name="q" value="<?=htmlspecialchars($q)?>" placeholder="Search by book name, author or category..."><button class="primary-small" type="submit">🔍 Search</button><?php if($q!==''): ?><a class="secondary-btn" href="view_books.php">Clear</a><?php endif; ?></form></div><div class="table-card"><div class="table-wrap"><table><thead><tr><th>ID</th><th>Book Name</th><th>Author</th><th>Category</th><th>ISBN</th><th>Available</th><?php if($admin): ?><th>Actions</th><?php else: ?><th>Action</th><?php endif; ?></tr></thead><tbody><?php if($result->num_rows===0): ?><tr><td colspan="7" class="empty">No books found.</td></tr><?php else: while($row=$result->fetch_assoc()): ?><tr><td>#<?= (int)$row['id'] ?></td><td><strong><?=htmlspecialchars($row['book_name'])?></strong></td><td><?=htmlspecialchars($row['author'])?></td><td><span class="category-tag"><?=htmlspecialchars($row['category'])?></span></td><td><?=htmlspecialchars($row['isbn'])?></td><td><span class="qty"><?= (int)$row['quantity'] ?></span></td><td><?php if($admin): ?><div class="table-actions"><a class="edit-btn" href="edit_book.php?id=<?= (int)$row['id'] ?>">Edit</a><a class="delete-btn" href="delete_book.php?id=<?= (int)$row['id'] ?>" onclick="return confirm('Delete this book?')">Delete</a></div><?php elseif(isset($activeBooks[(int)$row['id']])): ?><span class="status-issued">Already Borrowed</span><?php elseif((int)$row['quantity']<1): ?><span class="status-returned">Unavailable</span><?php else: ?><a class="borrow-btn" href="borrow_book.php?id=<?= (int)$row['id'] ?>">Borrow</a><?php endif; ?></td></tr><?php endwhile; endif; ?></tbody></table></div></div></main></body></html>
